using System;using System.Linq;using UnityEngine.InputSystem;using UnityEngine.InputSystem.Controls;using UnityEngine.InputSystem.LowLevel;
// Settings-only capture. Battle input remains sampled with zero grace.
public sealed class KeyBindingCapture:IDisposable {
 readonly KeyConfigProfile profile;readonly bool trigger;bool armed;ButtonControl candidate;string value;bool pad;public bool Complete{get;private set;}public string Value=>value;public bool Pad=>pad;public string Status{get;private set;}="すべてのボタンを離してください";
 public KeyBindingCapture(KeyConfigProfile profile,bool trigger){this.profile=profile;this.trigger=trigger;InputSystem.onEvent+=OnEvent;}
 static bool Supported(InputDevice d)=>d is Keyboard||d is Gamepad||d is Joystick;
 static bool Noise(InputControl c){string p=c.path.Substring(c.device.path.Length+1);return p.StartsWith("leftStick/")||p.StartsWith("rightStick/")||p.StartsWith("stick/");}
 static bool Held(){return InputSystem.devices.Where(Supported).SelectMany(d=>d.allControls).OfType<ButtonControl>().Any(c=>c.name!="anyKey"&&!Noise(c)&&c.isPressed);}
 static bool Matches(InputControl c,string path)=>!string.IsNullOrEmpty(path)&&InputControlPath.Matches(path,c);
 static float ReadButton(ButtonControl b,InputEventPtr evt)=>b.ReadValueFromEvent(evt,out float v)?v:b.ReadValue();
 void OnEvent(InputEventPtr evt,InputDevice device){if(!armed||Complete||candidate!=null||!Supported(device)||!evt.IsA<StateEvent>()&&!evt.IsA<DeltaStateEvent>())return;foreach(var control in evt.EnumerateChangedControls(device,.75f)){if(!(control is ButtonControl button)||control.name=="anyKey"||Noise(control)||ReadButton(button,evt)<.75f)continue;bool isPad=!(device is Keyboard);string t1=isPad?profile.Row("trigger.T1").pad:profile.Row("trigger.T1").keyboard,t2=isPad?profile.Row("trigger.T2").pad:profile.Row("trigger.T2").keyboard;if(!trigger&&(Matches(control,t1)||Matches(control,t2))){Status="修飾を押したまま、組み合わせるボタンを押してください";continue;}int modifier=0;if(!trigger){foreach(var c in device.allControls.OfType<ButtonControl>().Where(c=>ReadButton(c,evt)>.5f)){if(Matches(c,t1))modifier|=1;if(Matches(c,t2))modifier|=2;}if(modifier==3){Status="T1+T2の同時使用は登録できません";return;}}string relative=control.path.Substring(device.path.Length+1);if(device is Keyboard&&(relative=="leftShift"||relative=="rightShift"))relative="shift";if(device is Keyboard&&(relative=="leftCtrl"||relative=="rightCtrl"))relative="ctrl";string root=device is Keyboard?"<Keyboard>/":device is Gamepad?"<Gamepad>/":"<Joystick>/";candidate=button;pad=isPad;value=(modifier==1?"T1+":modifier==2?"T2+":"")+root+relative;Status="離すと登録: "+value;return;}}
 public void Tick(){if(Complete)return;if(candidate!=null&&!candidate.device.added){candidate=null;value=null;armed=false;Status="機器が切断されました。別の入力か取消を選んでください";return;}if(!armed){if(!Held()){armed=true;Status="Keyboard / Pad を入力（取消は画面のボタン）";}return;}if(candidate!=null&&!Held()){Complete=true;Status="入力を取得しました";}}
 public void Dispose(){InputSystem.onEvent-=OnEvent;}
}
